}

#include <Servo.h>

Servo myservo;
int pos = 0;

void setup() {
  Serial.begin(115200);
  myservo.attach(D1);  // attaches the servo on pin D1
  Serial.println("Servo controller ready!");
}

void loop() {
  for (pos = 0; pos <= 180; pos += 1) {
    myservo.write(pos);
    delay(15);
  }
  for (pos = 180; pos >= 0; pos -= 1) {
    myservo.write(pos);
    delay(15);
  }
}

